const quizLabels={all:'Mixed mission',devops:'DevOps delivery',cloud:'Cloud infrastructure',platform:'Kubernetes & reliability'};
let quizGame=null,quizTopic='all',quizDifficulty='all',quizRecorded=false;
let quizStats={xp:0,runs:0,best:0};
try{const s=JSON.parse(localStorage.getItem('flightpath-quiz-v1')||'null');if(s&&['xp','runs','best'].every(k=>Number.isSafeInteger(s[k])&&s[k]>=0))quizStats=s;}catch{}
function quizPage(){return `<section class="arena"><div class="arena-heading"><div><div class="eyebrow">FLIGHTPATH / QUIZ ARENA</div><h1>Practice under pressure.<br><em>Learn without the risk.</em></h1><p>Small missions. Real engineering decisions. Every answer teaches you something.</p></div><div class="arena-emblem" aria-hidden="true">⌘<span>LEARN · PLAY · LEVEL UP</span></div></div><div class="arena-stats"><div><small>TOTAL XP</small><strong>${quizStats.xp.toLocaleString()}</strong></div><div><small>COMPLETED MISSIONS</small><strong>${quizStats.runs}</strong></div><div><small>BEST MISSION</small><strong>${quizStats.best} <span>XP</span></strong></div><div><small>YOUR RANK</small><strong class="rank">${quizStats.xp>=3000?'Systems navigator':quizStats.xp>=1000?'Cloud explorer':'Curious apprentice'}</strong></div></div><div id="quiz-panel"></div><p class="arena-foot">24 curated questions · Untimed practice · Progress saved in this browser only</p></section>`;}
function quizLobby(){const panel=$('#quiz-panel');panel.innerHTML=`<div class="section-head"><h2>Choose your mission</h2><span class="tag">4–5 QUESTIONS / ROUND</span></div><div class="mission-tracks">${Object.entries(quizLabels).map(([id,label],i)=>`<button class="mission-track ${quizTopic===id?'selected':''}" data-topic="${id}" aria-pressed="${quizTopic===id}"><span class="mission-icon">${['✧','⑂','◇','⎈'][i]}</span><b>${label}</b><small>${['A little of everything','Git, CI/CD & runtime','IAM, networking & recovery','Workloads, probes & SLOs'][i]}</small><span class="track-count">${id==='all'?24:8} questions in bank ↗</span></button>`).join('')}</div><div class="mission-launch card"><div><label for="quiz-difficulty">Challenge level</label><select id="quiz-difficulty"><option value="all">Mixed difficulty</option><option value="foundation">Foundations</option><option value="advanced">Advanced scenarios</option></select></div><p>100 XP per correct answer.<br>Build a streak for up to 100 bonus XP per answer.</p><button class="btn teal" id="quiz-start">Start mission ↗</button></div><div class="callout">Choose an answer to see the explanation, then move on when you’re ready. A wrong answer resets your streak, but never ends your mission. Repeated missions also earn practice XP.</div>`;$('#quiz-difficulty').value=quizDifficulty;document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{quizTopic=b.dataset.topic;quizLobby()});$('#quiz-difficulty').onchange=e=>quizDifficulty=e.target.value;$('#quiz-start').onclick=()=>{quizGame=QuizCore.create(QuizCore.select(quizTopic,quizDifficulty));quizRecorded=false;quizQuestion();};}
function quizQuestion(){const g=quizGame,q=g.questions[g.index],a=g.answers[g.index];$('#quiz-panel').innerHTML=`<div class="question-shell card"><div class="question-meta"><span class="tag">${quizLabels[q.topic]} / ${q.difficulty}</span><button class="text-button" id="quiz-exit">End mission</button></div><div class="question-progress"><span>Question ${g.index+1} of ${g.questions.length}</span><span>${g.score} XP &nbsp; · &nbsp; ${g.streak} streak</span></div><div class="quiz-meter"><i style="width:${(g.index+(a?1:0))/g.questions.length*100}%"></i></div><h2 tabindex="-1" id="question-title">${q.prompt}</h2><div class="quiz-options">${q.options.map((o,i)=>`<button class="quiz-option ${a?(i===q.correct?'correct':i===a.choice?'incorrect':''):''}" data-answer="${i}" ${a?'disabled':''}><span>${String.fromCharCode(65+i)}</span><b>${o}</b>${a&&i===q.correct?'<small>✓ Correct answer</small>':a&&i===a.choice?'<small>✕ Your answer</small>':''}</button>`).join('')}</div>${a?`<div class="answer-feedback ${a.correct?'good':'learn'}" role="status"><b>${a.correct?'Well played. +'+a.points+' XP':'A useful lesson. Keep going.'}</b><p>${q.explanation}</p><a href="${q.source}" target="_blank" rel="noopener noreferrer">Read the official reference ↗</a></div><button class="btn teal" id="quiz-next">${g.index===g.questions.length-1?'See mission results':'Next question'} →</button>`:'<p class="question-hint">One answer per question. Take your time.</p>'}</div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(QuizCore.answer(g,Number(b.dataset.answer))){quizQuestion();$('#quiz-next').focus();}});$('#quiz-exit').onclick=()=>{if(confirm('End this mission? Unfinished mission XP will not be saved.')){quizGame=null;quizLobby();}};if($('#quiz-next'))$('#quiz-next').onclick=()=>{if(QuizCore.next(g)){if(g.finished)quizResults();else{quizQuestion();$('#question-title').focus();}}};}
function quizResults(){const result=QuizCore.summarize(quizGame);let storageNotice='';if(!quizRecorded){quizStats.xp+=result.score;quizStats.runs++;quizStats.best=Math.max(quizStats.best,result.score);quizRecorded=true;try{localStorage.setItem('flightpath-quiz-v1',JSON.stringify(quizStats));}catch{storageNotice='Browser storage is unavailable. These stats will last only for this session.';}}$('#quiz-panel').innerHTML=`<div class="result-banner card"><span class="result-seal" aria-hidden="true">${result.correct===result.total?'✧':'↗'}</span><div class="eyebrow">MISSION COMPLETE</div><h2 tabindex="-1" id="result-title">${result.correct===result.total?'A flawless flight.':result.correct>=result.total/2?'Your skills are taking shape.':'Every attempt builds understanding.'}</h2><p>You answered ${result.correct} of ${result.total} correctly. Review your decisions below.</p><div class="result-metrics"><strong>+${result.score}<small>MISSION XP</small></strong><strong>${Math.round(result.correct/result.total*100)}%<small>ACCURACY</small></strong><strong>${result.bestStreak}<small>BEST STREAK</small></strong></div><button class="btn teal" id="quiz-replay">Choose another mission ↗</button><a class="btn" href="#concepts">Study the field notes</a>${storageNotice?`<p role="status">${storageNotice}</p>`:''}</div><div class="section-head"><h2>Your mission debrief</h2><span class="tag">REVIEW & REFLECT</span></div><div class="quiz-review">${quizGame.questions.map((q,i)=>{const a=quizGame.answers[i];return `<details class="card"><summary><span class="review-mark">${a.correct?'✓':'↗'}</span>${q.prompt}<span>+</span></summary><p><b>Your answer:</b> ${q.options[a.choice]}</p>${a.correct?'':`<p><b>Correct answer:</b> ${q.options[q.correct]}</p>`}<p>${q.explanation}</p><a class="text-link" href="${q.source}" target="_blank" rel="noopener noreferrer">Official reference ↗</a></details>`;}).join('')}</div>`;$('#quiz-replay').onclick=()=>{quizGame=null;render();};$('#result-title').focus();document.querySelector('.arena-stats').innerHTML=`<div><small>TOTAL XP</small><strong>${quizStats.xp.toLocaleString()}</strong></div><div><small>COMPLETED MISSIONS</small><strong>${quizStats.runs}</strong></div><div><small>BEST MISSION</small><strong>${quizStats.best} <span>XP</span></strong></div><div><small>YOUR RANK</small><strong class="rank">${quizStats.xp>=3000?'Systems navigator':quizStats.xp>=1000?'Cloud explorer':'Curious apprentice'}</strong></div>`;}
function initQuiz(){if(quizGame?.finished)quizResults();else if(quizGame)quizQuestion();else quizLobby();}
